package com.bank.motivation;

import com.bank.motivation.model.CandidateGoals;
import com.bank.motivation.model.CompanyProfile;
import com.bank.motivation.service.MotivationMatcher;
import java.util.List;
import java.util.logging.*;

// Runnable demo: match "why this company" reasons to specific company attributes.
public class MotivationDemo {
    private static final Logger log = Logger.getLogger("Motivation");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        // Researched, company-specific attributes.
        CompanyProfile company = new CompanyProfile(
            "National Bank of India",
            List.of("event-driven core banking",
                    "real-time UPI settlement",
                    "in-house fraud platform",
                    "40M transactions/day"));

        CandidateGoals goals = new CandidateGoals(
            List.of("real-time settlement", "fraud platform", "high scale"));

        MotivationMatcher matcher = new MotivationMatcher(log);

        // Generic reason — recyclable, matches nothing specific.
        matcher.evaluate(company, goals, "You are a reputable company with good growth.");

        // Researched reason — links a specific attribute to a specific goal.
        matcher.evaluate(company, goals,
            "Your in-house fraud platform and real-time UPI settlement are exactly the "
              + "high-scale, real-time domain I want to specialize in.");
    }
}
